def load() -> pd.DataFrame:
    import pandas as pd, glob
    pattern = 'data/astronomy/input/swarmb/SB_DNS_POD_2024_*.txt'
    files = sorted(glob.glob(pattern))
    if len(files) == 0:
        raise FileNotFoundError(f'No files matched: {pattern}')
    return pd.DataFrame({'path': files})

def process(swarmBFilesList) -> pd.DataFrame:
    import pandas as pd
    paths = swarmBFilesList['path'].tolist()
    if not paths:
        raise ValueError('No Swarm-B files found')
    path = sorted(paths)[0]
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        lines = f.readlines()[:250]
    return pd.DataFrame({'path':[path]*len(lines), 'line_no': list(range(len(lines))), 'line':[l.rstrip('\n') for l in lines]})

def process(omni2Spec) -> pd.DataFrame:
    import pandas as pd
    text = omni2Spec['content'].iloc[0]
    # Keep only the part that enumerates the 55 columns (to help mapping)
    lines = text.splitlines()
    keep = []
    in_block = False
    for line in lines:
        if 'YEAR' in line and 'DOY' in line and ('HR' in line or 'HOUR' in line):
            in_block = True
        if in_block:
            keep.append(line)
        # stop after a long separator once we've started
        if in_block and ('---' in line) and len(keep) > 30:
            break
    if not keep:
        keep = lines[:200]
    return pd.DataFrame({'line_no': list(range(len(keep))), 'line': keep})

def process(omni2Spec) -> pd.DataFrame:
    import pandas as pd, re
    txt = omni2Spec['content'].iloc[0]
    # Try to find the table describing columns for hourly OMNI2; keep lines containing 'Col' and key words.
    lines = txt.splitlines()
    keep = []
    for i, line in enumerate(lines):
        if re.search(r'\bF10\.7\b|\bF107\b|AP\b|\bAp\b|\bDST\b|\bAE\b|\bKp\b', line):
            keep.append((i, line))
    # Also include any nearby 'COL'/'COLUMN' heading blocks
    more = []
    for i, line in enumerate(lines):
        if re.search(r'(?i)col\.?\s*\d+|column\s+\d+', line):
            more.append((i, line))
    out = pd.DataFrame(keep + more, columns=['line_no','line']).drop_duplicates().sort_values('line_no').reset_index(drop=True)
    return out
